    instance.domain === 'interval'
      ? '时间轴动态规划；反例额外进行子集枚举'
      : instance.domain === 'knapsack'
        ? '折半子集枚举'
        : '独立 Bellman–Ford';
  return {
    ...base,
    difference,
    verdict: failure ? 'counterexample' : 'pass',
    details: [
      failure
        ? candidate.complete
          ? `候选值 ${candidate.value}，精确参照值 ${reference.value}，差距 ${difference}。`
