export function knapsackOptimal(instance: KnapsackInstance): Execution {
  const items = [...instance.items].sort((a, b) => lexical(a.id, b.id));
  const capacity = instance.capacity,
    rows: Int32Array[] = [new Int32Array(capacity + 1)],
    take: Uint8Array[] = [];
  const steps: TraceStep[] = [];
  function solution(prefix: number): string[] {
    const ids: string[] = [];
    let remaining = capacity;
    for (let k = prefix - 1; k >= 0; k--)
      if (take[k][remaining]) {
        ids.push(items[k].id);
        remaining -= items[k].weight;
      }
    return ids.reverse();
  }
  for (let i = 0; i < items.length; i++) {
    const item = items[i],
      previous = rows[i],
      row = new Int32Array(previous),
      chosen = new Uint8Array(capacity + 1);
    for (let c = item.weight; c <= capacity; c++) {
      const candidate = previous[c - item.weight] + item.value;
      if (candidate > previous[c]) {
        row[c] = candidate;
        chosen[c] = 1;
      }
    }
    rows.push(row);
    take.push(chosen);
    const ids = solution(i + 1);
    emit(steps, {
      kind: ids.includes(item.id) ? 'select' : 'reject',
      message: `前 ${i + 1} 件的容量动态规划完成：容量 ${capacity} 的最优价值 ${row[capacity]}。`,
      activeIds: [item.id],
      selectedIds: ids,
      currentValue: row[capacity],
      data: { prefix: i + 1, capacity, previousValue: previous[capacity], bestValue: row[capacity] },
    });
  }
