    '全部项目已按确定的排序与平局规则处理。',
  );
}

export function intervalOptimal(instance: IntervalInstance): Execution {
  const items = [...instance.items].sort((a, b) => a.end - b.end || a.start - b.start || lexical(a.id, b.id));
  const values = [0],
    solutions: string[][] = [[]],
    steps: TraceStep[] = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    let predecessor = i - 1;
    while (predecessor >= 0 && items[predecessor].end > item.start) predecessor--;
    const take = values[predecessor + 1] + (instance.objective === 'count' ? 1 : item.value),
      skip = values[i];
    const chosen = take > skip;
    values.push(chosen ? take : skip);
    solutions.push(chosen ? [...solutions[predecessor + 1], item.id] : [...solutions[i]]);
    emit(steps, {
      kind: chosen ? 'select' : 'reject',
      message: `前 ${i + 1} 项：选 ${item.label} 得 ${take}，不选得 ${skip}；保存最优值 ${values[i + 1]}。`,
      activeIds: [item.id],
      selectedIds: solutions[i + 1],
      currentValue: values[i + 1],
      data: { take, skip, predecessor: predecessor >= 0 ? items[predecessor].id : null, prefix: i + 1 },
    });
  }
  return finished(
    solutions.at(-1)!,
    values.at(-1)!,
    steps,
    '按结束时间排序的精确动态规划已完成；相等时保留前一解。',
  );
}

