export type Domain = 'interval' | 'knapsack' | 'graph';
export type Objective = 'value' | 'count';
export interface IntervalItem { id: string; label: string; start: number; end: number; value: number }
export interface KnapsackItem { id: string; label: string; weight: number; value: number }
export interface GraphNode { id: string; label: string; x: number; y: number }
export interface GraphEdge { id: string; from: string; to: string; weight: number }
export interface IntervalInstance { domain: 'interval'; items: IntervalItem[]; objective: Objective }
export interface KnapsackInstance { domain: 'knapsack'; items: KnapsackItem[]; capacity: number }
export interface GraphInstance { domain: 'graph'; nodes: GraphNode[]; edges: GraphEdge[]; source: string; target: string; directed: boolean }
export type Instance = IntervalInstance | KnapsackInstance | GraphInstance;
export interface Strategy { id: string; name: string; domain: Domain; algorithm: 'greedy' | 'optimal' | 'dijkstra' | 'local'; score: string; direction: 'asc' | 'desc'; tieBreak: 'id' | 'value' | 'weight' | 'start' | 'end' }
export interface TraceStep { index: number; kind: 'consider' | 'select' | 'reject' | 'visit' | 'relax' | 'finish'; message: string; activeIds: string[]; selectedIds: string[]; currentValue: number; rejectedIds?: string[]; frontier?: {id:string;distance:number}[]; data?: Record<string,unknown> }
export interface Execution { solutionIds: string[]; value: number; feasible: boolean; complete: boolean; reason?: string; steps: TraceStep[]; pathNodeIds?: string[] }
export interface Evaluation { instance: Instance; strategy: Strategy; candidate: Execution; reference: Execution; verdict: 'counterexample' | 'pass' | 'invalid' | 'incomplete'; difference: number; witnessVerified: boolean; details: string[] }
export interface SearchOptions { domain: Domain; strategy: Strategy; seed: number; attempts: number; size: number; maxValue?: number; objective?: Objective }
export interface SearchProgress { checked: number; total: number; found: number }
export interface SearchResult { status: 'counterexample' | 'not_found' | 'incomplete'; checked: number; total: number; seed: number; elapsedMs: number; evaluation?: Evaluation; reason?: string; samples?: {index:number;gap:number}[] }
export interface ShrinkStep { description: string; beforeSize: number; afterSize: number; instance: Instance; evaluation: Evaluation }
export interface ShrinkResult { original: Evaluation; final: Evaluation; steps: ShrinkStep[]; checks: number; minimality: 'reduced' | 'local'; elapsedMs: number }
export interface RegressionRow { label: string; instance: Instance; before: Evaluation; after: Evaluation; change: 'improved' | 'regressed' | 'unchanged' }
export interface RegressionResult { rows: RegressionRow[]; improved: number; regressed: number; unchanged: number; seed: number }
export interface Experiment { id: string; title: string; domain: Domain; createdAt: string; updatedAt: string; instance: Instance; strategy: Strategy; versions: {id:string;at:string;strategy:Strategy;note:string}[]; evaluation?: Evaluation; search?: SearchResult; shrink?: ShrinkResult; regression?: RegressionResult }
export interface ExperimentPackage { format: 'counterlab-experiment'; version: 1; engineVersion: string; exportedAt: string; experiment: Experiment; checksum: string }
export interface JobStatus { id: string; kind: 'search' | 'shrink' | 'regression'; state: 'queued' | 'running' | 'completed' | 'cancelled' | 'failed'; progress: SearchProgress; result?: SearchResult | ShrinkResult | RegressionResult; error?: string }
export interface AiStatus { configured: boolean; provider: string; model: string; baseUrl: string; calls: number; inputTokens: number; outputTokens: number }
export interface AiProposal { strategy: Strategy; explanation: string; assumptions: string[]; source: 'live-model' }

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { randomUUID,createHash,timingSafeEqual } from 'node:crypto';
import { ENGINE_VERSION } from '../src/engine/index.ts';
import type { Experiment,ExperimentPackage,JobStatus } from '../src/shared/types.ts';
import { packageSchema,trustedSave,validateExperimentVersions } from './validation.ts';

export function canonical(value:unknown):string {
  if(value===null||typeof value!=='object')return JSON.stringify(value);
  if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';
  return '{'+Object.entries(value).filter(([,v])=>v!==undefined).sort(([a],[b])=>a<b?-1:a>b?1:0).map(([k,v])=>JSON.stringify(k)+':'+canonical(v)).join(',')+'}';
}
export function checksum(value:unknown){return createHash('sha256').update(canonical(value)).digest('hex')}
export class Store {
  private db:DatabaseSync;
  constructor(filename:string){
    const path=resolve(filename);if(process.platform==='win32' && !/^D:\\/i.test(path))throw new Error('数据库必须位于 D 盘');
    mkdirSync(dirname(path),{recursive:true});this.db=new DatabaseSync(path);
    this.db.exec('PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS experiments(id TEXT PRIMARY KEY, updated_at TEXT NOT NULL, data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, data TEXT NOT NULL)');
    for(const row of this.db.prepare('SELECT id,data FROM jobs').all()){
      const job=JSON.parse(String(row.data)) as JobStatus;
      if(job.state==='running'||job.state==='queued'){job.state='failed';job.error='服务已重启，本次任务中断。已保存的实验未受影响，请重新运行。';this.saveJob(job);}
    }
  }
  list():Experiment[]{return this.db.prepare('SELECT data FROM experiments ORDER BY updated_at DESC').all().map(row=>JSON.parse(String(row.data)))}
  get(id:string):Experiment|undefined {const row=this.db.prepare('SELECT data FROM experiments WHERE id=?').get(id);return row?JSON.parse(String(row.data)):undefined}
  save(input:unknown,id?:string):Experiment {
    const values=trustedSave(input);const previous=id?this.get(id):undefined;
    if(id&&!previous)throw new Error('实验不存在');
    if(previous && previous.domain!==values.instance.domain)throw new Error('已有实验不能切换领域，请另存新实验');
    const at=new Date().toISOString();const changed=!previous||canonical(previous.strategy)!==canonical(values.strategy);
    const versions=previous?[...previous.versions]:[];
    if(changed){if(versions.length>=200)throw new Error('策略版本已达到200个，请导出并创建新实验');versions.push({id:randomUUID(),at,strategy:values.strategy,note:previous?'策略修改':'初始策略'});}
    const experiment:Experiment={...values,id:previous?.id??randomUUID(),domain:values.instance.domain,createdAt:previous?.createdAt??at,updatedAt:at,versions} as Experiment;
    this.write(experiment);return experiment;
  }
  private write(experiment:Experiment){this.db.prepare('INSERT INTO experiments(id,updated_at,data) VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET updated_at=excluded.updated_at,data=excluded.data').run(experiment.id,experiment.updatedAt,JSON.stringify(experiment))}
  delete(id:string){return this.db.prepare('DELETE FROM experiments WHERE id=?').run(id).changes>0}
  export(id:string):ExperimentPackage|undefined {
    const experiment=this.get(id);if(!experiment)return undefined;
    const payload={format:'counterlab-experiment' as const,version:1 as const,engineVersion:ENGINE_VERSION,exportedAt:new Date().toISOString(),experiment};return {...payload,checksum:checksum(payload)};
  }
  import(input:unknown):Experiment {
    const pkg=packageSchema.parse(input);const {checksum:expected,...payload}=pkg;
    if(!timingSafeEqual(Buffer.from(expected,'hex'),Buffer.from(checksum(payload),'hex')))throw new Error('实验包校验和不匹配，文件可能已改变');
    if(pkg.engineVersion!==ENGINE_VERSION)throw new Error('执行器版本不兼容，不能静默迁移实验');
    validateExperimentVersions(pkg.experiment as Experiment);
    const {id:_id,createdAt,updatedAt:_updated,domain:_domain,versions,...values}=pkg.experiment;
    const verified=trustedSave(values);const at=new Date().toISOString();
    const experiment={...verified,id:randomUUID(),domain:verified.instance.domain,createdAt,updatedAt:at,versions} as Experiment;
    this.write(experiment);return experiment;
  }
  saveJob(job:JobStatus){this.db.prepare('INSERT INTO jobs(id,data) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data').run(job.id,JSON.stringify(job))}
  getJob(id:string):JobStatus|undefined{const row=this.db.prepare('SELECT data FROM jobs WHERE id=?').get(id);return row?JSON.parse(String(row.data)):undefined}
  close(){this.db.close()}
}
import { Worker } from 'node:worker_threads';
import { randomUUID } from 'node:crypto';
import type { JobStatus, SearchProgress } from '../src/shared/types.ts';
import type { Store } from './store.ts';

type Entry={status:JobStatus;payload:unknown;cancel:SharedArrayBuffer;worker?:Worker;timer?:ReturnType<typeof setTimeout>};
export class JobError extends Error{statusCode=429}
export class Jobs {
  private entries=new Map<string,Entry>();private active=0;private closing=false;
  constructor(private store:Store,private timeoutMs=45000){}
  create(kind:JobStatus['kind'],payload:unknown):JobStatus{
    if(this.closing)throw new JobError('服务正在关闭');
    if([...this.entries.values()].filter(e=>['queued','running'].includes(e.status.state)).length>=8)throw new JobError('任务队列已满，请等待或取消现有任务');
    this.prune();
    const status:JobStatus={id:randomUUID(),kind,state:'queued',progress:{checked:0,total:0,found:0}};
    this.entries.set(status.id,{status,payload,cancel:new SharedArrayBuffer(4)});this.store.saveJob(status);
    queueMicrotask(()=>this.pump());return structuredClone(status);
  }
  get(id:string){const status=this.entries.get(id)?.status??this.store.getJob(id);return status?structuredClone(status):undefined}
  cancel(id:string):JobStatus|undefined{
    const entry=this.entries.get(id);if(!entry)return this.store.getJob(id);
    if(!['queued','running'].includes(entry.status.state))return entry.status;
    Atomics.store(new Int32Array(entry.cancel),0,1);entry.status.state='cancelled';
    entry.status.error='用户取消了任务，不能将其解释为未找到反例。';this.store.saveJob(entry.status);
    if(entry.timer)clearTimeout(entry.timer);
    if(entry.worker)void entry.worker.terminate();else this.pump();return entry.status;
  }
  private pump(){
    if(this.closing||this.active>=1)return;
    const entry=[...this.entries.values()].find(e=>e.status.state==='queued');if(!entry)return;
    this.active++;entry.status.state='running';this.store.saveJob(entry.status);
    let worker:Worker;
    try{worker=new Worker(new URL('./job-worker.mjs',import.meta.url),{workerData:{kind:entry.status.kind,payload:entry.payload,cancel:entry.cancel},execArgv:[],resourceLimits:{maxOldGenerationSizeMb:192,maxYoungGenerationSizeMb:32}});}
    catch{entry.status.state='failed';entry.status.error='无法启动计算进程，请检查本地运行环境。';this.store.saveJob(entry.status);this.active--;queueMicrotask(()=>this.pump());return;}
    entry.worker=worker;
    worker.on('message',(message:{type:string;progress?:SearchProgress;result?:JobStatus['result'];error?:string})=>{
      if(entry.status.state!=='running')return;
      if(message.type==='progress'&&message.progress)entry.status.progress=message.progress;
      else if(message.type==='result'){entry.status.state='completed';entry.status.result=message.result;}
      else if(message.type==='error'){entry.status.state='failed';entry.status.error=message.error?.slice(0,500)??'计算失败';}
      this.store.saveJob(entry.status);
    });
    worker.on('error',()=>{if(entry.status.state==='running'){entry.status.state='failed';entry.status.error='计算进程异常退出，实验数据未改变。';this.store.saveJob(entry.status);}});
    worker.on('exit',()=>{
      if(entry.timer)clearTimeout(entry.timer);
      if(entry.status.state==='running'){entry.status.state='failed';entry.status.error='计算进程未返回完整结果。';this.store.saveJob(entry.status);}
      entry.worker=undefined;this.active--;
      this.prune();
      this.pump();
    });
    entry.timer=setTimeout(()=>{if(entry.status.state==='running'){entry.status.state='failed';entry.status.error='任务超过计算时限；搜索未完成，不代表不存在反例。';this.store.saveJob(entry.status);void worker.terminate();}},this.timeoutMs);
  }
  private prune(){for(const [id,item]of this.entries){if(this.entries.size<100)break;if(!item.worker&&!['queued','running'].includes(item.status.state))this.entries.delete(id);}}
  async close(){
    this.closing=true;const pending:Promise<number>[]=[];
    for(const entry of this.entries.values()){
      if(['running','queued'].includes(entry.status.state)){entry.status.state='failed';entry.status.error='服务关闭导致任务中断，请重新运行。';this.store.saveJob(entry.status);}
      if(entry.timer)clearTimeout(entry.timer);if(entry.worker)pending.push(entry.worker.terminate());
    }
    await Promise.all(pending);
  }
}

