import { useRef, useState } from 'react';
import { ArrowUpRight, Crosshair, Network, CircleDot, ScanLine } from 'lucide-react';
import type { Evaluation, Execution, GraphInstance, Instance, TraceStep } from '../../shared/types';

const stage = (execution: Execution | undefined, step: number) => execution?.steps[Math.min(step, execution.steps.length - 1)];
function selectedAt(execution: Execution | undefined, step: number) { return stage(execution, step)?.selectedIds ?? []; }

function IntervalTrack({ instance, execution, step, tone, hovered, setHovered }: { instance: Extract<Instance, {domain:'interval'}>; execution?: Execution; step: number; tone: string; hovered: string | null; setHovered: (id: string | null) => void }) {
  const min = Math.min(0, ...instance.items.map(i => i.start));
  const max = Math.max(1, ...instance.items.map(i => i.end));
  const x = (time: number) => 65 + (time - min) / (max - min) * 535;
  const selected = selectedAt(execution, step); const current = stage(execution, step);
  const height = Math.max(164, 58 + instance.items.length * 35);
  return <svg className={`interval-svg ${tone}`} viewBox={`0 0 650 ${height}`} role="img" aria-label={`${tone === 'candidate' ? '候选' : '参照'}区间执行轨迹`}>
    {Array.from({ length: 9 }, (_, index) => { const value = min + (max - min) * index / 8; return <g key={index}><line className="grid-line" x1={x(value)} x2={x(value)} y1={26} y2={height - 14} /><text className="axis-text" x={x(value)} y={15} textAnchor="middle">{Number.isInteger(value) ? value : Number(value.toFixed(1))}</text></g>; })}
    {instance.items.map((item, index) => { const isSelected = selected.includes(item.id); const active = current?.activeIds.includes(item.id); const rejected = current?.rejectedIds?.includes(item.id); const y = 38 + index * 35; return <g tabIndex={0} role="button" aria-label={`${item.label}，时间 ${item.start} 到 ${item.end}，收益 ${item.value}${isSelected ? '，已选择' : ''}`} key={item.id} onMouseEnter={() => setHovered(item.id)} onMouseLeave={() => setHovered(null)} onFocus={() => setHovered(item.id)} onBlur={() => setHovered(null)} className={`interval-object ${isSelected ? 'selected' : ''} ${active ? 'active' : ''} ${rejected ? 'rejected' : ''} ${hovered === item.id ? 'hovered' : ''}`}>
      <text className="object-axis" x={25} y={y + 17}>{item.id}</text><rect x={x(item.start)} y={y} width={Math.max(4, x(item.end) - x(item.start))} height={25} rx={4} />
      <text className="bar-text" x={x(item.start) + 10} y={y + 17}>{x(item.end) - x(item.start) > 72 ? `${item.id} · ${item.value}` : item.id}</text>
      {isSelected && x(item.end) - x(item.start) > 45 && <text className="bar-check" x={x(item.end) - 12} y={y + 17} textAnchor="middle">✓</text>}
    </g>; })}
  </svg>;
}

function KnapsackTrack({ instance, execution, step, tone, hovered, setHovered }: { instance: Extract<Instance,{domain:'knapsack'}>; execution?: Execution; step: number; tone: string; hovered: string | null; setHovered: (id:string|null) => void }) {
  const selected = selectedAt(execution, step); const active = stage(execution, step)?.activeIds ?? [];
  const weight = instance.items.filter(i => selected.includes(i.id)).reduce((total, item) => total + item.weight, 0);
  return <div className={`knapsack-plot ${tone}`}><div className="capacity-label"><span>已用容量 <b>{weight}</b> / {instance.capacity}</span><span>{Math.round(weight / Math.max(1, instance.capacity) * 100)}%</span></div><div className="capacity-track">{instance.items.filter(i => selected.includes(i.id)).map(item => <span key={item.id} style={{ width: `${item.weight / Math.max(1, instance.capacity) * 100}%` }} title={`${item.id}：重量 ${item.weight}`}>{item.id}</span>)}</div><div className="item-grid">{instance.items.map(item => <button key={item.id} className={`knapsack-item ${selected.includes(item.id) ? 'selected' : ''} ${active.includes(item.id) ? 'active' : ''} ${hovered === item.id ? 'hovered' : ''}`} onMouseEnter={() => setHovered(item.id)} onMouseLeave={() => setHovered(null)} onFocus={() => setHovered(item.id)} onBlur={() => setHovered(null)}><span className="item-corner">{item.id}</span><strong>{item.value}<small>收益</small></strong><span className="item-weight">重量 {item.weight}</span>{selected.includes(item.id) && <span className="item-selected">✓</span>}</button>)}</div></div>;
}

export function GraphPlot({ instance, execution, step = 0, tone = 'candidate', onChange }: { instance: GraphInstance; execution?: Execution; step?: number; tone?: string; onChange?: (instance: GraphInstance) => void }) {
  const svg = useRef<SVGSVGElement>(null);
  const drag = useRef<string | null>(null);
  const maxX = Math.max(1, ...instance.nodes.map(n => n.x)); const maxY = Math.max(1, ...instance.nodes.map(n => n.y));
  const positions = Object.fromEntries(instance.nodes.map((node, i) => [node.id, { x: 60 + (Number.isFinite(node.x) ? node.x / maxX : i / Math.max(1, instance.nodes.length - 1)) * 520, y: 35 + (Number.isFinite(node.y) ? node.y / maxY : 0.5) * 110 }]));
  const current = stage(execution, step); const selected = current?.selectedIds ?? []; const active = current?.activeIds ?? [];
  return <svg ref={svg} className={`graph-svg ${tone}`} viewBox="0 0 650 195" role="img" aria-label="路由网络与当前执行状态" onPointerMove={e => { if (!drag.current || !onChange || !svg.current) return; const rect = svg.current.getBoundingClientRect(); const rawX = (e.clientX - rect.left) / rect.width * 650; const rawY = (e.clientY - rect.top) / rect.height * 195; onChange({ ...instance, nodes: instance.nodes.map(n => n.id === drag.current ? { ...n, x: Math.max(0, Math.min(maxX, (rawX - 60) / 520 * maxX)), y: Math.max(0, Math.min(maxY, (rawY - 35) / 110 * maxY)) } : n) }); }} onPointerUp={() => { drag.current = null; }} onPointerCancel={() => { drag.current = null; }}>
    <defs><marker id={`arrow-${tone}`} viewBox="0 0 10 10" refX="25" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor" /></marker></defs>
    {instance.edges.map(edge => { const from = positions[edge.from]; const to = positions[edge.to]; if (!from || !to) return null; const picked = selected.includes(edge.id); return <g key={edge.id} className={`graph-edge ${picked ? 'selected' : ''} ${active.includes(edge.id) ? 'active' : ''}`}><line x1={from.x} y1={from.y} x2={to.x} y2={to.y} markerEnd={instance.directed ? `url(#arrow-${tone})` : undefined} /><rect x={(from.x + to.x) / 2 - 11} y={(from.y + to.y) / 2 - 10} width="22" height="20" rx="6" /><text x={(from.x + to.x) / 2} y={(from.y + to.y) / 2 + 4} textAnchor="middle">{edge.weight}</text></g>; })}
    {instance.nodes.map(node => { const position = positions[node.id]; const visited = selected.includes(node.id) || current?.data?.node === node.id || (execution?.pathNodeIds?.includes(node.id) && current?.kind === 'finish'); return <g key={node.id} className={`graph-node ${visited ? 'selected' : ''} ${active.includes(node.id) ? 'active' : ''}`} tabIndex={0} role="button" aria-label={`节点 ${node.id}${node.id === instance.source ? '，起点' : node.id === instance.target ? '，终点' : ''}`} onPointerDown={e => { if (onChange) { drag.current = node.id; e.currentTarget.setPointerCapture(e.pointerId); } }}><circle cx={position.x} cy={position.y} r="20" /><text x={position.x} y={position.y + 5} textAnchor="middle">{node.id}</text><text className="node-label" x={position.x} y={position.y + 37} textAnchor="middle">{node.id === instance.source ? '起点' : node.id === instance.target ? '终点' : node.label !== node.id ? node.label : ''}</text></g>; })}
  </svg>;
}

export function TraceCanvas({ instance, evaluation, step, hovered, setHovered }: { instance: Instance; evaluation: Evaluation | null; step: number; hovered: string | null; setHovered: (id:string|null) => void }) {
  const tracks = [{ key: 'candidate', label: '候选策略', caption: evaluation?.strategy.name || '等待执行', execution: evaluation?.candidate }, { key: 'reference', label: '精确参照', caption: '独立核验的最优结果', execution: evaluation?.reference }];
  return <div className="twin-canvas"><div className="canvas-heading"><div><span className="eyebrow">SYNCHRONIZED EXECUTION</span><h2>同一个问题，两条执行路径<span className="live-dot" /></h2></div><div className="canvas-legend"><span><i className="legend-dot coral" />候选</span><span><i className="legend-dot blue" />参照</span><span><i className="legend-outline" />未选</span></div></div>
    {tracks.map((track, index) => { const current = stage(track.execution, step); return <section key={track.key} className={`trace-track ${track.key}`}><div className="track-header"><div className="track-heading"><span className="track-index">0{index + 1}</span><div><h3>{track.label}</h3><span>{track.caption}</span></div></div><div className="track-value"><span>{instance.domain === 'graph' ? '路径代价' : instance.domain === 'interval' && instance.objective === 'count' ? '已选任务' : '累计收益'}</span><strong>{track.execution ? !track.execution.complete && current?.kind === 'finish' ? '—' : current?.currentValue ?? 0 : '—'}</strong></div></div>
      <div className="track-plot">{instance.domain === 'interval' ? <IntervalTrack instance={instance} execution={track.execution} step={step} tone={track.key} hovered={hovered} setHovered={setHovered} /> : instance.domain === 'knapsack' ? <KnapsackTrack instance={instance} execution={track.execution} step={step} tone={track.key} hovered={hovered} setHovered={setHovered} /> : <GraphPlot instance={instance} execution={track.execution} step={step} tone={track.key} />}</div>
      <div className="track-event"><CircleDot size={13} /><span>{current?.message || (evaluation ? '此轨迹没有更多步骤。' : '调整左侧策略与场景，然后运行实验。')}</span><code>{current ? `STEP ${String(current.index + 1).padStart(2, '0')}` : 'READY'}</code></div>
    </section>; })}
    <div className="canvas-foot"><span><Crosshair size={13} />{hovered ? `对象 ${hovered} · 双轨联动高亮` : '悬停对象，比较两条轨迹中的同一选择'}</span><span><ScanLine size={13} />真实执行轨迹</span></div>
  </div>;
}

export function EventList({ steps, step }: { steps: TraceStep[]; step: number }) { return <div className="event-list">{steps.map((event, index) => <div key={index} className={`event-row ${index === step ? 'current' : ''}`}><span>{String(index + 1).padStart(2, '0')}</span><p>{event.message}</p><b>{event.currentValue}</b></div>)}</div>; }
import { useEffect, useRef, type ReactNode } from 'react';
import { X } from 'lucide-react';

export function Modal({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const dialog = useRef<HTMLDialogElement>(null);
  useEffect(() => { const node = dialog.current; node?.showModal(); return () => { node?.close(); }; }, []);
  return <dialog ref={dialog} className={`modal ${wide ? 'modal-wide' : ''}`} onCancel={onClose} onClick={event => { if (event.target === dialog.current) onClose(); }}>
    <div className="modal-header"><div><span className="eyebrow">COUNTERLAB / WORKSPACE</span><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button type="button" className="icon-button" aria-label="关闭对话框" onClick={onClose}><X size={20} /></button></div>
    {children}
  </dialog>;
}
import { Plus, Trash2, ArrowRight, Info } from 'lucide-react';
import type { Instance } from '../../shared/types';
import { clone } from '../api';

const nextId = (existing: string[], prefix = '') => { let i = 0; while (existing.includes(`${prefix}${String.fromCharCode(65 + i)}`)) i++; return `${prefix}${String.fromCharCode(65 + i)}`; };
export function InstanceEditor({ instance, onChange }: { instance: Instance; onChange: (value: Instance) => void }) {
  const update = (fn: (copy: Instance) => void) => { const copy = clone(instance); fn(copy); onChange(copy); };
  const num = (value: string) => Number(value);
  if (instance.domain === 'graph') return <div className="instance-editor">
    <div className="editor-options"><label>起点<select value={instance.source} onChange={e => update(i => { if (i.domain === 'graph') i.source = e.target.value; })}>{instance.nodes.map(n => <option key={n.id}>{n.id}</option>)}</select></label><ArrowRight size={15} /><label>终点<select value={instance.target} onChange={e => update(i => { if (i.domain === 'graph') i.target = e.target.value; })}>{instance.nodes.map(n => <option key={n.id}>{n.id}</option>)}</select></label><label className="check-label"><input type="checkbox" checked={instance.directed} onChange={e => update(i => { if (i.domain === 'graph') i.directed = e.target.checked; })} />有向图</label></div>
    <div className="editor-section-title">节点 <button className="text-button" onClick={() => update(i => { if (i.domain === 'graph') { const id = nextId(i.nodes.map(n => n.id)); i.nodes.push({ id, label: id, x: 80 + i.nodes.length * 40, y: 100 }); } })}><Plus size={13} />添加节点</button></div>
    <div className="node-editor-list">{instance.nodes.map(n => <span className="node-editor" key={n.id}><b>{n.id}</b><input aria-label={`节点 ${n.id} 名称`} value={n.label} onChange={e => update(i => { if (i.domain === 'graph') i.nodes.find(x => x.id === n.id)!.label = e.target.value; })} /><button className="icon-button small" aria-label={`删除节点 ${n.id}`} disabled={instance.nodes.length <= 2} onClick={() => update(i => { if (i.domain === 'graph') { i.nodes = i.nodes.filter(x => x.id !== n.id); i.edges = i.edges.filter(x => x.from !== n.id && x.to !== n.id); if (i.source === n.id) i.source = i.nodes[0].id; if (i.target === n.id) i.target = i.nodes.at(-1)!.id; } })}><Trash2 size={12} /></button></span>)}</div>
    <div className="table-scroll"><table className="input-table"><thead><tr><th>边</th><th>从</th><th>到</th><th>权重</th><th /></tr></thead><tbody>{instance.edges.map((edge, idx) => <tr key={edge.id}><td><span className="object-id">{edge.id}</span></td><td><select aria-label={`边 ${edge.id} 起点`} value={edge.from} onChange={e => update(i => { if (i.domain === 'graph') i.edges[idx].from = e.target.value; })}>{instance.nodes.map(n => <option key={n.id}>{n.id}</option>)}</select></td><td><select aria-label={`边 ${edge.id} 终点`} value={edge.to} onChange={e => update(i => { if (i.domain === 'graph') i.edges[idx].to = e.target.value; })}>{instance.nodes.map(n => <option key={n.id}>{n.id}</option>)}</select></td><td><input type="number" min="0" aria-label={`边 ${edge.id} 权重`} value={edge.weight} onChange={e => update(i => { if (i.domain === 'graph') i.edges[idx].weight = num(e.target.value); })} /></td><td><button className="icon-button small" aria-label={`删除边 ${edge.id}`} onClick={() => update(i => { if (i.domain === 'graph') i.edges.splice(idx, 1); })}><Trash2 size={13} /></button></td></tr>)}</tbody></table></div>
    <button className="add-row" onClick={() => update(i => { if (i.domain === 'graph') i.edges.push({ id: nextId(i.edges.map(e => e.id), 'e'), from: i.nodes[0].id, to: i.nodes.at(-1)!.id, weight: 1 }); })}><Plus size={14} />添加一条边</button>
    <p className="field-note"><Info size={13} />权重必须为非负整数。节点可在场景图中拖动。</p>
