import { useEffect, useRef, useState } from 'react';
import { ArrowRight, Beaker, BookOpen, Check, ChevronLeft, ChevronRight, Download, FileText, FlaskConical, FolderOpen, History, Lightbulb, LoaderCircle, Pause, Play, Plus, RotateCcw, Save, Search, Settings2, ShieldCheck, SkipBack, Sparkles, Upload, X } from 'lucide-react';
import type { AiProposal, AiStatus, Domain, Evaluation, Experiment, ExperimentPackage, Instance, JobStatus, RegressionResult, SearchResult, ShrinkResult, Strategy } from '../shared/types';
import { validateInstance, validateStrategy } from '../engine/validation';
import { api, clone, domainLabels, initialInstance, initialStrategy, type Catalog } from './api';
import { Modal } from './components/Modal';
import { InstanceEditor } from './components/InstanceEditor';
import { EventList, GraphPlot, TraceCanvas } from './components/TraceCanvas';

interface Draft { id?: string; title: string; instance: Instance; strategy: Strategy; versions: Experiment['versions']; evaluation?: Evaluation; search?: SearchResult; shrink?: ShrinkResult; regression?: RegressionResult }
type Panel = 'editor' | 'library' | 'versions' | 'help' | 'events' | 'shrink' | 'regression' | null;
const blank = (): Draft => ({ title: '我的第一个反例实验', instance: clone(initialInstance), strategy: clone(initialStrategy), versions: [] });
const verdictText = { counterexample: '发现了一个反例', pass: '当前实例通过', invalid: '策略无法执行', incomplete: '计算未完成' };
const sizeOf = (i: Instance) => i.domain === 'graph' ? i.nodes.length + i.edges.length : i.items.length;
const valueOf = (e: Evaluation, side: 'candidate' | 'reference') => e.instance.domain === 'graph' && !e[side].complete ? (side === 'candidate' && e.reference.complete ? '未到达' : '不可达') : e[side].value;
const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);
const DRAFT_KEY = 'counterlab.draft.v1';

export default function App() {
  const [catalog, setCatalog] = useState<Catalog | null>(null);
  const [draft, setDraft] = useState<Draft>(blank);
  const [library, setLibrary] = useState<Experiment[]>([]);
  const [ai, setAi] = useState<AiStatus | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [job, setJob] = useState<JobStatus | null>(null);
  const [notice, setNotice] = useState<{ text: string; error?: boolean } | null>(null);
  const [panel, setPanel] = useState<Panel>(null);
  const [editor, setEditor] = useState<Instance>(clone(initialInstance));
  const [step, setStep] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [hovered, setHovered] = useState<string | null>(null);
  const [intent, setIntent] = useState('');
  const [proposal, setProposal] = useState<AiProposal | null>(null);
  const [explanation, setExplanation] = useState('');
  const [baseline, setBaseline] = useState<Evaluation | null>(null);
  const [seed, setSeed] = useState(20261115);
  const [attempts, setAttempts] = useState(300);
  const [searchSize, setSearchSize] = useState(7);
  const [holdout, setHoldout] = useState(30);
  const [draftReady, setDraftReady] = useState(false);
  const [autosave, setAutosave] = useState('草稿仅保存在此浏览器');
  const fileInput = useRef<HTMLInputElement>(null);
  const draftRef = useRef(draft); draftRef.current = draft;
  const running = job?.state === 'queued' || job?.state === 'running';
  const locked = Boolean(busy || running);
  const entry = catalog?.domains.find(item => item.domain === draft.instance.domain);
  const evaluation = draft.evaluation ?? null;
  const maxStep = Math.max(0, Math.max(evaluation?.candidate.steps.length ?? 0, evaluation?.reference.steps.length ?? 0) - 1);
  const variables = draft.instance.domain === 'interval' ? ['start', 'end', 'duration', 'value'] : draft.instance.domain === 'knapsack' ? ['weight', 'value'] : ['weight'];
  const ties = draft.instance.domain === 'interval' ? ['id', 'value', 'start', 'end'] : draft.instance.domain === 'knapsack' ? ['id', 'value', 'weight'] : ['id', 'weight'];

  async function connect() {
    setBusy('连接本地服务'); setNotice(null);
    try {
      const [nextCatalog, saved, status] = await Promise.all([api.catalog(), api.experiments(), api.aiStatus()]);
      setCatalog(nextCatalog); setLibrary(saved); setAi(status);
      if (!draftReady) {
        let restored = false;
        try {
          const raw = localStorage.getItem(DRAFT_KEY);
          if (raw) { const value = JSON.parse(raw); validateInstance(value.instance); validateStrategy(value.strategy); if (value.instance.domain !== value.strategy.domain || typeof value.title !== 'string' || value.title.length > 120) throw new Error();
            const stored = saved.find(e => e.id === value.id);
            setDraft({ title: value.title, instance: value.instance, strategy: value.strategy, versions: stored?.versions ?? [], id: stored?.id });
            setNotice({ text: '已恢复本地草稿。请重新运行以更新计算结论。' }); restored = true;
          }
        } catch { setNotice({ text: '旧草稿无法恢复，已保留保存的实验，可从实验档案打开。', error: true }); }
        if (!restored) { const first = nextCatalog.domains[0]; setDraft({ ...blank(), instance: first.instance, strategy: first.strategy }); }
        setDraftReady(true);
      }
    } catch (error) { setNotice({ text: error instanceof Error ? error.message : '连接失败', error: true }); }
    finally { setBusy(null); }
  }
  useEffect(() => { void connect(); }, []);
  useEffect(() => {
    if (!draftReady) return;
    const timer = window.setTimeout(() => {
      try { localStorage.setItem(DRAFT_KEY, JSON.stringify({ id: draft.id, title: draft.title, instance: draft.instance, strategy: draft.strategy })); setAutosave('草稿已自动保存'); }
      catch { setAutosave('草稿存储不可用，请保存到实验档案'); }
    }, 450);
    return () => clearTimeout(timer);
  }, [draft.id, draft.title, draft.instance, draft.strategy, draftReady]);
  useEffect(() => { if (!playing) return; const timer = setInterval(() => setStep(current => { if (current >= maxStep) { setPlaying(false); return maxStep; } return current + 1; }), 800); return () => clearInterval(timer); }, [playing, maxStep]);
  useEffect(() => {
    if (!job || !['queued', 'running'].includes(job.state)) return;
    let cancelled = false; let timer: ReturnType<typeof setTimeout>;
    const poll = async () => {
      try {
        const next = await api.job(job.id); if (cancelled) return; setJob(next);
        if (next.state === 'completed' && next.result) {
          setPlaying(false); setStep(0);
          if (next.kind === 'search') { const result = next.result as SearchResult; setDraft(current => ({ ...current, search: result, shrink: undefined, regression: undefined, ...(result.evaluation ? { instance: result.evaluation.instance, evaluation: result.evaluation } : {}) })); if (result.evaluation) setBaseline(result.evaluation); setNotice({ text: result.status === 'counterexample' ? `第 ${result.checked} 个样本找到并核验了反例。` : '本轮采样未找到反例，不代表策略普遍正确。' }); }
          if (next.kind === 'shrink') { const result = next.result as ShrinkResult; setDraft(current => ({ ...current, instance: result.final.instance, evaluation: result.final, shrink: result, regression: undefined })); setBaseline(result.final); setNotice({ text: `完成 ${result.steps.length} 个有效缩减步骤，每一步保持同一失败条件。` }); }
          if (next.kind === 'regression') { const result = next.result as RegressionResult; setDraft(current => ({ ...current, regression: result, evaluation: result.rows[0]?.after ?? current.evaluation })); setPanel('regression'); }
        } else if (next.state === 'failed' || next.state === 'cancelled') setNotice({ text: next.error || '计算未完成，请重新运行。', error: next.state === 'failed' });
        else timer = setTimeout(poll, 250);
      } catch (error) { if (!cancelled) { setNotice({ text: `${error instanceof Error ? error.message : '连接中断'}；任务状态将在连接恢复后重试。`, error: true }); timer = setTimeout(poll, 1500); } }
    };
    timer = setTimeout(poll, 100); return () => { cancelled = true; clearTimeout(timer); };
  }, [job?.id, job?.state]);
  useEffect(() => { const protect = (event: BeforeUnloadEvent) => { if (locked) { event.preventDefault(); event.returnValue = ''; } }; window.addEventListener('beforeunload', protect); return () => window.removeEventListener('beforeunload', protect); }, [locked]);

  async function action<T>(label: string, work: () => Promise<T>): Promise<T | undefined> {
    setBusy(label); setNotice(null);
    try { return await work(); } catch (error) { setNotice({ text: error instanceof Error ? error.message : '操作失败，请重试。', error: true }); return undefined; } finally { setBusy(null); }
  }
  function changeStrategy(strategy: Strategy) { if (locked) return; if (draft.evaluation) setBaseline(draft.evaluation); setDraft(current => ({ ...current, strategy, evaluation: undefined, search: undefined, shrink: undefined, regression: undefined })); setExplanation(''); setPlaying(false); setStep(0); }
  function newDomain(domain: Domain) { const next = catalog?.domains.find(d => d.domain === domain); if (!next || locked) return; setDraft({ title: `${next.title} · 新实验`, instance: clone(next.instance), strategy: clone(next.strategy), versions: [] }); setBaseline(null); setExplanation(''); setJob(null); setHovered(null); setPlaying(false); setStep(0); setNotice(null); }
  async function run() { const result = await action('执行并独立核验', () => api.evaluate(draft.instance, draft.strategy)); if (result) { setDraft(current => ({ ...current, evaluation: result })); setBaseline(result); setStep(0); setPlaying(false); setExplanation(''); } }
  async function save(): Promise<Experiment | undefined> { return action('保存实验快照', async () => { const current = draftRef.current; const saved = await api.save({ title: current.title, instance: current.instance, strategy: current.strategy, evaluation: current.evaluation, search: current.search, shrink: current.shrink, regression: current.regression }, current.id); setDraft(saved); setLibrary(await api.experiments()); setNotice({ text: `已保存「${saved.title}」，共 ${saved.versions.length} 个版本。` }); return saved; }); }
  function openSaved(saved: Experiment) { setDraft(clone(saved)); setBaseline(saved.evaluation ?? null); setStep(0); setPlaying(false); setExplanation(''); setJob(null); setPanel(null); setNotice({ text: `已打开「${saved.title}」。` }); }
  async function startSearch() { const next = await action('启动反例搜索', () => api.search({ domain: draft.instance.domain, strategy: draft.strategy, seed, attempts, size: searchSize, maxValue: 20, ...(draft.instance.domain === 'interval' ? { objective: draft.instance.objective } : {}) })); if (next) { setJob(next); setExplanation(''); } }
  async function startShrink() { if (!evaluation) return; const next = await action('启动性质保持缩减', () => api.shrink(evaluation)); if (next) setJob(next); }
  async function startRegression() { const before = baseline?.strategy ?? draft.versions.at(-2)?.strategy; if (!before) return; const next = await action('启动历史与保留集回归', () => api.regression(draft.instance, before, draft.strategy, seed, holdout)); if (next) setJob(next); }
  async function cancelJob() { if (!job) return; const next = await action('取消计算', () => api.cancel(job.id)); if (next) { setJob(next); setNotice({ text: next.state === 'cancelled' ? '计算已取消。不能把取消解释为没有反例。' : '任务已经结束。' }); } }
  async function download(kind: 'export' | 'report') { const saved = await save(); if (!saved) return; const link = document.createElement('a'); link.href = `/api/experiments/${encodeURIComponent(saved.id)}/${kind}`; link.download = ''; document.body.append(link); link.click(); link.remove(); }
  async function importFile(file: File | undefined) { if (!file) return; if (file.size > 16 * 1024 * 1024) { setNotice({ text: '实验包不能超过 16 MiB。', error: true }); return; } const saved = await action('校验实验包并重新计算', async () => api.import(JSON.parse(await file.text()) as ExperimentPackage)); if (saved) { openSaved(saved); setLibrary(await api.experiments()); setNotice({ text: '实验包已导入，输入与结论已重新计算。' }); } }
  async function propose() { const result = await action('AI 正在整理策略契约', () => api.propose(draft.instance.domain, intent, draft.strategy)); if (result) setProposal(result); void api.aiStatus().then(setAi).catch(() => {}); }
