import type { Experiment } from '../src/shared/types.ts';
export function escapeHtml(value: unknown) {
  return String(value ?? '').replace(
    /[&<>"']/g,
    (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]!,
  );
}
export function report(experiment: Experiment, engineVersion: string) {
  const e = experiment.evaluation;
  const verdict = e
    ? {
        counterexample: '已验证反例',
        pass: '当前实例通过',
        invalid: '实例/策略无效',
        incomplete: '计算未完成',
      }[e.verdict]
    : '尚未计算';
  const trace = (title: string, steps: NonNullable<typeof e>['candidate']['steps']) =>
    `<section><h2>${title}</h2><ol>${steps.map((step) => `<li><strong>${escapeHtml(step.kind)}</strong> ${escapeHtml(step.message)} <small>当前值 ${escapeHtml(step.currentValue)}</small></li>`).join('')}</ol></section>`;
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(experiment.title)} · CounterLab</title><style>body{font:16px/1.7 system-ui,sans-serif;max-width:960px;margin:40px auto;padding:0 24px;color:#252522;background:#faf8f2}h1{font-size:32px}h2{margin-top:32px;font-size:21px}small{color:#64645d}pre{padding:18px;background:#efeee7;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:12px}.verdict{border-left:4px solid #b64a35;padding:12px 18px;background:#f3e9e0}li{margin-bottom:8px}footer{margin-top:40px;border-top:1px solid #ccc;padding-top:20px}</style></head><body><header><small>COUNTERLAB / 可重放算法实验</small><h1>${escapeHtml(experiment.title)}</h1><p>${escapeHtml(experiment.domain)} · 执行器 ${escapeHtml(engineVersion)} · 更新 ${escapeHtml(experiment.updatedAt)}</p></header><div class="verdict"><strong>${verdict}</strong>${e ? `<p>候选值：${escapeHtml(e.candidate.value)}；参考值：${escapeHtml(e.reference.value)}；差距：${escapeHtml(e.difference)}</p><p>${e.details.map(escapeHtml).join('<br>')}</p>` : ''}<p>结论仅适用于本报告输入。有限样本通过不构成普遍正确性证明；不可达时的数值哨兵不表示存在零成本路径。</p></div><h2>策略契约</h2><pre>${escapeHtml(JSON.stringify(experiment.strategy, null, 2))}</pre><h2>实验输入</h2><pre>${escapeHtml(JSON.stringify(experiment.instance, null, 2))}</pre>${e ? trace('候选策略的真实执行轨迹', e.candidate.steps) + trace('参考解的真实执行轨迹', e.reference.steps) : ''}<h2>策略版本</h2><ol>${experiment.versions.map((v) => `<li>${escapeHtml(v.at)} · ${escapeHtml(v.strategy.name)} · ${escapeHtml(v.note)}</li>`).join('')}</ol><footer>本报告由本地程序生成。结论在保存/导入时重新计算；完整重放请使用JSON实验包。${experiment.shrink ? '已保存缩减证据；导入重算反例不代表证明全局最小性。' : ''}</footer></body></html>`;
}

